<script setup lang="ts">
import type { ProviderId } from '../../infrastructure/providers';
import { computed, ref, watch } from 'vue';
import UButton from '@nuxt/ui/components/Button.vue';
import UInput from '@nuxt/ui/components/Input.vue';
import USelect from '@nuxt/ui/components/Select.vue';
import { state, workspaceAction } from '../store';
const provider = ref<ProviderId>('codex-cli'), executable = ref(''), model = ref(''), key = ref(''), clearKey = ref(false), url = ref(''), enrollment = ref(''), busy = ref(false), message = ref('');
const selected = computed(() => state.settings?.providers.find(item => item.id === provider.value));
function fillProvider() { executable.value = selected.value?.executable ?? ''; model.value = selected.value?.model ?? ''; key.value = ''; clearKey.value = false; }
watch(provider, fillProvider);
watch(() => state.unlocked, value => { if (value) { fillProvider(); url.value = state.settings?.connection.url ?? ''; } else { key.value = ''; enrollment.value = ''; executable.value = ''; model.value = ''; url.value = ''; message.value = ''; } }, { immediate: true });
watch(() => !!state.settings, value => { if (value) { fillProvider(); url.value = state.settings?.connection.url ?? ''; } });
async function save(body: unknown) { busy.value = true; message.value = ''; try { if (await workspaceAction('/api/settings', body)) { key.value = ''; enrollment.value = ''; clearKey.value = false; message.value = 'Settings saved.'; } } finally { busy.value = false; } }
</script>
<template>
<section v-if="state.unlocked" class="monitor-section"><h2>Connections</h2><div class="settings-grid"><form class="settings-form" @submit.prevent="save({ provider: { id: provider, executable, model, apiKey: key, clearApiKey: clearKey } })"><h3>Model provider</h3><label for="provider-connection">Connection</label><USelect id="provider-connection" v-model="provider" :items="state.settings?.providers.map(item => ({ label: item.label, value: item.id })) ?? []" class="w-full" /><template v-if="provider.endsWith('-cli')"><label for="provider-path">CLI executable on this machine</label><UInput id="provider-path" v-model="executable" placeholder="/absolute/path/to/codex" class="w-full" /><p class="page-note">Uses the worker process owner’s existing CLI login. Sign in on the machine first. Installation, subscription quota and login are not verified here. Subscription CLIs currently require Linux or macOS.</p></template><template v-else><label for="provider-model">Model ID</label><UInput id="provider-model" v-model="model" required placeholder="An available model from your provider" class="w-full" /><label for="provider-key">API key</label><UInput id="provider-key" v-model="key" type="password" autocomplete="off" :placeholder="selected?.hasApiKey ? 'Key saved · leave blank to keep' : 'Paste provider API key'" class="w-full" /><label class="check-label"><input v-model="clearKey" type="checkbox"> Remove saved API key</label><p class="page-note">Keys are stored privately on the worker machine and are never returned to the browser. API calls use your provider billing.</p></template><UButton type="submit" :loading="busy">Save provider</UButton></form><form class="settings-form" @submit.prevent="save({ connection: { enabled: true, url, enrollmentToken: enrollment } })"><h3>Optional orchestrator</h3><p>{{ state.settings?.connection.enabled ? 'This worker is configured to register and accept orchestrator tasks.' : 'Standalone · chat, sessions and local tasks work without an orchestrator.' }}</p><label for="orchestrator-url">Orchestrator address</label><UInput id="orchestrator-url" v-model="url" type="url" placeholder="http://127.0.0.1:3000" required class="w-full" /><label for="enrollment-token">Enrollment token</label><UInput id="enrollment-token" v-model="enrollment" type="password" autocomplete="off" :placeholder="state.settings?.connection.hasEnrollmentToken ? 'Token saved · leave blank to keep' : 'From your orchestrator administrator'" class="w-full" /><div class="actions"><UButton type="submit" :loading="busy">Save &amp; connect</UButton><UButton v-if="state.settings?.connection.enabled" color="neutral" variant="outline" :disabled="busy" @click="save({ connection: { enabled: false } })">Go standalone</UButton></div><p class="page-note">Registration retries automatically. Pause intake and finish assigned tasks before disconnecting. A registered identity remains bound to its original orchestrator.</p></form></div><p v-if="message" role="status">{{ message }}</p><p v-if="state.actionError" role="alert" class="error-text">{{ state.actionError }}</p></section>
</template>
